import "server-only";
import { db } from "@/lib/db";
import { PLANS } from "@/lib/plans";
import { DAILY_EMAIL_LIMIT } from "@/lib/email-limits";
export async function publicPlanCopy() {
  const control = await db.systemControl.findUnique({
    where: { key: "global" },
    select: { paidGatingEnabled: true },
  });
  const gated = control?.paidGatingEnabled === true;
  return {
    gated,
    campaignRecipients: gated
      ? PLANS.FREE.campaignRecipients
      : PLANS.PAID.campaignRecipients,
    description: gated
      ? `Free includes ${PLANS.FREE.monthlyEmails} emails/month, ${PLANS.FREE.dailyEmails}/day and ${PLANS.FREE.campaignRecipients}/campaign. Premium includes ${PLANS.PAID.monthlyEmails}/month, ${PLANS.PAID.dailyEmails}/day and ${PLANS.PAID.campaignRecipients}/campaign.`
      : `Send up to ${PLANS.PAID.campaignRecipients} recipients per campaign, within ${DAILY_EMAIL_LIMIT} emails per rolling 24 hours.`,
  };
}
